"""
ScholaCore stack switch: HTML/CSS/JS/PHP.

This DELETES every tracked file currently in the repo (the Vite +
TypeScript + Node scaffold from the previous rebuild) and replaces it
with:

  - Plain HTML/CSS/JS, no build step, no bundler, no TypeScript.
    Firebase and Tailwind load directly from CDNs via native
    <script type="module"> imports.
  - PHP serverless functions under api/, deployed via the COMMUNITY
    vercel-php runtime (vercel-community/php, vercel-php@0.9.0) --
    Vercel has no official first-party PHP runtime.
  - Firebase Firestore/Storage/Auth kept as-is, accessed server-side
    from PHP via the COMMUNITY kreait/firebase-php SDK -- there is no
    official Google Firebase Admin SDK for PHP.
  - firebase/firestore.rules and firebase/storage.rules carried over
    unchanged (three-role model: student/teacher/admin).
  - Paystack webhook (HMAC-verified via hash_equals, idempotent) and
    single-use Telegram invite delivery (createChatInviteLink with
    member_limit: 1), ported from the TypeScript version with the same
    decoupled-failure design: a Telegram delivery failure never undoes
    or blocks a student's paid status.
  - Client-facing config (Firebase web config, Paystack public key) is
    served at request time by api/firebase-config.php and
    api/paystack-config.php, reading real environment variables --
    nothing hardcoded into a static committed JS file.

Two things you must do after this runs, before it will actually work:
  1. Run `composer install` in the repo (or let Vercel's build do it --
     vercel-php supports Composer natively) so vendor/ exists.
  2. Set every variable in .env.example in Vercel's Environment
     Variables settings.

This is destructive to the repo's tracked files. It does NOT touch git
history -- the previous Vite/TS version is still recoverable from past
commits -- but `main` will look completely different after this runs.

Run on your Windows machine with the repo already cloned.

Usage:
    python rebuild_scholacore_php.py [path_to_repo]
"""
import base64, os, subprocess, sys

DEFAULT_REPO = r"C:\Users\Bosslady\SCHOLACORE\scholacore"

FILES = {
    '.env.example': '',
    '.gitignore': 'dmVuZG9yLwouZW52Ci5lbnYubG9jYWwKLnZlcmNlbC8KKi5sb2cK',
    'README.md': '',
    'admin-dashboard.html': '',
    'api/_lib/FirebaseAdmin.php': '',
    'api/_lib/TelegramBot.php': '',
    'api/firebase-config.php': '',
    'api/paystack-config.php': '',
    'api/paystack-webhook.php': '',
    'assets/css/style.css': '',
    'assets/js/pages/admin-dashboard.js': '',
    'assets/js/pages/pay.js': '',
    'assets/js/pages/student-signup.js': '',
    'assets/js/pages/teacher-portal.js': '',
    'assets/js/pages/teacher-vetting.js': '',
    'assets/js/telegram.js': '',
    'composer.json': '',
    'firebase/firestore.rules': '',
    'firebase/schema.md': '',
    'firebase/storage.rules': '',
    'index.html': '',
    'pay.html': '',
    'privacy-policy.html': '',
    'student-signup.html': '',
    'teacher-portal.html': '',
    'teacher-vetting.html': '',
    'terms-of-service.html': '',
    'vercel.json': 'ewogICJmdW5jdGlvbnMiOiB7CiAgICAiYXBpLyoucGhwIjogewogICAgICAicnVudGltZSI6ICJ2ZXJjZWwtcGhwQDAuNy40IgogICAgfQogIH0KfQo=',
}


def run(cmd, cwd):
    print(">", " ".join(cmd))
    result = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
    if result.stdout.strip():
        print(result.stdout)
    if result.returncode != 0 and result.stderr.strip():
        print(result.stderr)
    return result.returncode == 0


def main():
    repo_root = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_REPO
    if not os.path.isdir(repo_root):
        print(f"Repo path not found: {repo_root}")
        sys.exit(1)

    git_dir = os.path.join(repo_root, ".git")
    if not os.path.isdir(git_dir):
        print(f"{repo_root} is not a git repository (no .git folder). Aborting.")
        sys.exit(1)

    result = subprocess.run(
        ["git", "ls-files"], cwd=repo_root, capture_output=True, text=True
    )
    tracked = [f for f in result.stdout.splitlines() if f.strip()]
    if tracked:
        if not run(["git", "rm", "-rf", "--cached", "."], repo_root):
            sys.exit(1)
        for rel in tracked:
            full = os.path.join(repo_root, rel.replace("/", os.sep))
            if os.path.isfile(full):
                os.remove(full)
        print(f"removed {len(tracked)} previously tracked files")

    for rel_path, b64_content in FILES.items():
        dest = os.path.join(repo_root, rel_path.replace("/", os.sep))
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "wb") as f:
            f.write(base64.b64decode(b64_content))
        print(f"wrote: {rel_path}")

    print(f"\n{len(FILES)} files written to {repo_root}")

    if not run(["git", "add", "-A"], repo_root):
        sys.exit(1)
    commit_msg = "Stack switch: HTML/CSS/JS frontend (no build step) + PHP backend (vercel-php runtime, kreait/firebase-php), Firebase/Paystack/Telegram unchanged"
    if not run(["git", "commit", "-m", commit_msg], repo_root):
        print("Nothing to commit or commit failed -- check output above.")
        sys.exit(1)
    run(["git", "push", "origin", "main"], repo_root)

    print("\nStill required before this works:")
    print("  1. composer install   (or let Vercel run it during deploy)")
    print("  2. Set every var in .env.example in Vercel's Environment Variables")


if __name__ == "__main__":
    main()
